<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Admin Login</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-green-50 flex items-center justify-center h-screen"><form action="/admin/login" method="post" class="bg-white p-8 rounded-2xl shadow-xl w-full max-w-md"><h1 class="text-2xl font-bold mb-4">Admin Login</h1><?php if(isset($error)) echo '<p class="text-red-500 mb-2">'.$error.'</p>'; if(isset($success)) echo '<p class="text-green-600 mb-2">'.$success.'</p>'; ?><input type="text" name="username" placeholder="Username" required class="w-full border rounded-lg px-3 py-2 mb-3"><input type="password" name="password" placeholder="Password" required class="w-full border rounded-lg px-3 py-2 mb-3"><button type="submit" class="w-full bg-green-600 text-white py-2 rounded-lg hover:bg-green-700">Login</button></form></body></html>